package tokenizer

import java.nio.charset.Charset
import java.time.{LocalDate, LocalDateTime}
import java.time.format.DateTimeFormatter

import scala.collection.mutable

import io.circe.Json

// ============================================================================
// Protocol-style traits
// ============================================================================

trait Tokenizable {
  def toToken: String
}

trait HasLength {
  def length: Int
  def size: Int = length
}

trait TokenProcessor[-T] {
  def process(item: T): Unit
}

// ============================================================================
// Token types and core token
// ============================================================================

sealed abstract class TokenType(val value: String)
object TokenType {
  case object STRING extends TokenType("string")
  case object NUMERIC extends TokenType("numeric")
  case object TEMPORAL extends TokenType("temporal")
  case object STRUCTURED extends TokenType("structured")
  case object BINARY extends TokenType("binary")
  case object NULL extends TokenType("null")
}

final case class Token(
  value: String,
  tokenType: TokenType,
  metadata: Map[String, Any] = Map.empty
) {
  def withMetadata(entries: (String, Any)*): Token = {
    if (entries.isEmpty) this
    else copy(metadata = metadata ++ entries.toMap)
  }
}

final class MutableTokenBatch {
  private val tokensBuffer = mutable.ListBuffer.empty[Token]
  private var processed = false

  def tokens: List[Token] = tokensBuffer.toList

  def add(token: Token): Unit = {
    if (processed) throw new RuntimeException("Batch already processed")
    tokensBuffer += token
  }

  def markProcessed(): Unit = {
    processed = true
  }

  def isProcessed: Boolean = processed
}

// ============================================================================
// Generic container classes
// ============================================================================

final class TokenContainer[+T](items: Seq[T]) {
  private val itemsVector: Vector[T] = items.toVector

  def getAll: Vector[T] = itemsVector

  def mapTokens(func: T => String): List[String] = itemsVector.map(func).toList

  def size: Int = itemsVector.size
}

final class TokenSink[-T] {
  private val received = mutable.ListBuffer.empty[Any]

  def receive(item: T): Unit = received += item

  def drain(): List[Any] = {
    val result = received.toList
    received.clear()
    result
  }
}

final class BivariantHandler[T](default: T) {
  private var value: T = default

  def get: T = value

  def set(next: T): Unit = {
    value = next
  }

  def transform(func: T => T): T = {
    value = func(value)
    value
  }
}

// ============================================================================
// Base tokenizer and implementations
// ============================================================================

abstract class BaseTokenizer[T] {
  def tokenize(value: T): Token

  def tokenizeBatch(values: Iterable[T]): Iterator[Token] = {
    values.iterator.map(tokenize)
  }
}

object StringTokenizer {
  sealed trait StringOrBytes
  final case class Text(value: String) extends StringOrBytes
  final case class Bytes(value: Array[Byte]) extends StringOrBytes
}

final class StringTokenizer(
  val encoding: String = "UTF-8",
  normalizer: String => String = identity
) extends BaseTokenizer[StringTokenizer.StringOrBytes] {

  override def tokenize(value: StringTokenizer.StringOrBytes): Token = {
    val strValue = value match {
      case StringTokenizer.Text(text) => text
      case StringTokenizer.Bytes(bytes) =>
        new String(bytes, Charset.forName(encoding))
    }
    val normalized = normalizer(strValue)
    Token(normalized, TokenType.STRING)
  }

  def tokenize(value: String): Token = tokenize(StringTokenizer.Text(value))

  def tokenize(value: Array[Byte]): Token = tokenize(StringTokenizer.Bytes(value))
}

final class NumericTokenizer(
  val precision: Int = 6,
  val formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[Any] {

  override def tokenize(value: Any): Token = {
    val strValue = value match {
      case d: BigDecimal => formatDecimal(d)
      case d: java.math.BigDecimal => formatDecimal(BigDecimal(d))
      case d: Double => f"$d%.${precision}f"
      case f: Float => f"$f%.${precision}f"
      case n: BigInt => n.toString
      case n: Byte => n.toString
      case n: Short => n.toString
      case n: Int => n.toString
      case n: Long => n.toString
      case n: java.lang.Number => n.toString
      case other =>
        throw new IllegalArgumentException(s"Unsupported numeric type: ${other.getClass.getName}")
    }

    val originalType = Option(value).map(_.getClass.getSimpleName).getOrElse("null")
    Token(strValue, TokenType.NUMERIC, Map("original_type" -> originalType))
  }

  private def formatDecimal(value: BigDecimal): String =
    value.setScale(precision, BigDecimal.RoundingMode.HALF_UP).toString
}

final class TemporalTokenizer(formatStr: Option[String] = None) extends BaseTokenizer[Any] {
  private val isoFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss")
  private val dateFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd")
  private val customFormatter = formatStr.map(DateTimeFormatter.ofPattern)

  override def tokenize(value: Any): Token = value match {
    case dt: LocalDateTime => Token(format(dt), TokenType.TEMPORAL)
    case d: LocalDate => Token(format(d), TokenType.TEMPORAL)
    case other =>
      throw new IllegalArgumentException(s"Unsupported temporal type: ${other.getClass.getName}")
  }

  def tokenize(value: LocalDateTime): Token = Token(format(value), TokenType.TEMPORAL)

  def tokenize(value: LocalDate): Token = Token(format(value), TokenType.TEMPORAL)

  private def format(value: LocalDateTime): String = {
    val formatter = customFormatter.getOrElse(isoFormatter)
    formatter.format(value)
  }

  private def format(value: LocalDate): String = {
    val formatter = customFormatter.getOrElse(dateFormatter)
    formatter.format(value)
  }
}

final class UniversalTokenizer {
  private val stringTokenizer = new StringTokenizer()
  private val numericTokenizer = new NumericTokenizer()
  private val temporalTokenizer = new TemporalTokenizer()

  def tokenizeNull: Token = Token("NULL", TokenType.NULL)

  def tokenize(value: Any): Token = value match {
    case null => tokenizeNull
    case tokenizable: Tokenizable =>
      Token(tokenizable.toToken, TokenType.STRUCTURED)
    case text: String => stringTokenizer.tokenize(text)
    case bytes: Array[Byte] => stringTokenizer.tokenize(bytes)
    case dt: LocalDateTime => temporalTokenizer.tokenize(dt)
    case d: LocalDate => temporalTokenizer.tokenize(d)
    case _: BigDecimal | _: BigInt | _: java.lang.Number =>
      numericTokenizer.tokenize(value)
    case other => Token(other.toString, TokenType.STRING, Map("fallback" -> true))
  }
}

// ============================================================================
// Complex nested generics
// ============================================================================

final class TokenRegistry[T] {
  private val registry = mutable.Map.empty[String, TokenContainer[T]]
  private val handlers = mutable.ListBuffer.empty[T => Option[Token]]

  def register(key: String, container: TokenContainer[T]): Unit = {
    registry.update(key, container)
  }

  def addHandler(handler: T => Option[Token]): Unit = {
    handlers += handler
  }

  def process(key: String): List[Option[Token]] = {
    registry.get(key) match {
      case None => List.empty
      case Some(container) =>
        container.getAll.toList.map { item =>
          val firstMatch = handlers.iterator
            .map(handler => handler(item))
            .find(_.isDefined)
          firstMatch.getOrElse(None)
        }
    }
  }
}

