type JsonValue = Json

final class JsonTokenizer(val pretty: Boolean = false) {
  def tokenize(value: JsonValue): Token = {
    val jsonString = if (pretty) value.spaces2 else value.noSpaces
    Token(jsonString, TokenType.STRUCTURED, Map("json" -> true))
  }

  def tokenizePath(value: JsonValue, path: String): Option[Token] = {
    if (path.trim.isEmpty) return Some(tokenize(value))

    val parts = path.split("\\.").toList

    def descend(current: Json, remaining: List[String]): Option[Json] = remaining match {
      case Nil => Some(current)
      case head :: tail if head.forall(_.isDigit) =>
        current.asArray.flatMap(_.lift(head.toInt)).flatMap(next => descend(next, tail))
      case head :: tail =>
        current.asObject.flatMap(_.apply(head)).flatMap(next => descend(next, tail))
    }

    descend(value, parts).map(tokenize)
  }
}

// ============================================================================
// Whitespace tokenizer
// ============================================================================

final class WhitespaceTokenizer(
  val lowercase: Boolean = false,
  val minLength: Int = 0,
  val maxLength: Option[Int] = None,
  val stripPunctuation: Boolean = false
) {
  private val punctuation = Set('.', ',', '!', '?', ';', ':', '\'', '"', '(', ')', '[', ']', '{', '}')

  private def stripPunct(word: String): String = {
    val leftTrimmed = word.dropWhile(punctuation.contains)
    leftTrimmed.reverse.dropWhile(punctuation.contains).reverse
  }

  private def splitWords(text: String): Array[String] = {
    val trimmed = text.trim
    if (trimmed.isEmpty) Array.empty
    else trimmed.split("\\s+")
  }

  private def processToken(word: String): Option[String] = {
    val stripped = if (stripPunctuation) stripPunct(word) else word
    val normalized = if (lowercase) stripped.toLowerCase else stripped

    if (normalized.length < minLength) return None

    val bounded = maxLength match {
      case Some(max) if normalized.length > max => normalized.take(max)
      case _ => normalized
    }

    if (bounded.isEmpty) None else Some(bounded)
  }

  def tokenize(text: String): List[Token] = {
    val words = splitWords(text)

    words.zipWithIndex.flatMap { case (word, index) =>
      processToken(word).map { processed =>
        Token(processed, TokenType.STRING, Map("position" -> index, "original" -> word))
      }
    }.toList
  }

  def tokenizeToStrings(text: String): List[String] = tokenize(text).map(_.value)

  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    val words = splitWords(text)
    val result = mutable.ListBuffer.empty[(String, Int, Int)]

    var currentPos = 0
    words.foreach { word =>
      val start = text.indexOf(word, currentPos)
      if (start >= 0) {
        val end = start + word.length
        processToken(word).foreach { processed =>
          result += ((processed, start, end))
        }
        currentPos = end
      }
    }

    result.toList
  }

  def countTokens(text: String): Int = tokenize(text).size
}

// ============================================================================
// Fluent tokenizer builder
// ============================================================================

final class TokenizerBuilder[T] private () {
  private val normalizers = mutable.ListBuffer.empty[String => String]
  private val validators = mutable.ListBuffer.empty[T => Boolean]
  private val metadata = mutable.Map.empty[String, Any]

  def withNormalizer(normalizer: String => String): TokenizerBuilder[T] = {
    normalizers += normalizer
    this
  }

  def withValidator(validator: T => Boolean): TokenizerBuilder[T] = {
    validators += validator
    this
  }

  def withMetadata(entries: (String, Any)*): TokenizerBuilder[T] = {
    metadata ++= entries
    this
  }

  def build(): T => Token = {
    val normalizersSnapshot = normalizers.toList
    val validatorsSnapshot = validators.toList
    val metadataSnapshot = metadata.toMap

    (value: T) => {
      validatorsSnapshot.foreach { validator =>
        if (!validator(value)) {
          throw new IllegalArgumentException(s"Validation failed for $value")
        }
      }

      val normalized = normalizersSnapshot.foldLeft(value.toString) { (current, normalizer) =>
        normalizer(current)
      }

      Token(normalized, TokenType.STRING, metadataSnapshot)
    }
  }
}

object TokenizerBuilder {
  def apply[T](): TokenizerBuilder[T] = new TokenizerBuilder[T]()
}
